```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb[vws.title]

key = vws["A7"].value
result = None

def same(a, b):
    if a is None or b is None:
        return a is b
    try:
        return float(a) == float(b)
    except (TypeError, ValueError):
        return str(a).strip() == str(b).strip()

# The formula’s lookup table is rows 1-5; use the available B column as the return column.
for r in range(1, 6):
    a = vws.cell(row=r, column=1).value
    if same(a, key):
        result = vws.cell(row=r, column=2).value
        break

if isinstance(result, str):
    result = result.strip()

ws["B7"] = result
wb.save(OUT)

print("key:", key, "result:", result)
